// This file is generated by AI.

//! `game/animation` 动画库。
//!
//! WebGAL 的自定义动画是一串关键帧 (v1 数组格式), 由引擎 `AnimationManager` 按
//! `game/animation/animationTable.json` 里的名字预加载; 动画名可以出现在
//! `changeBg` / `changeFigure` 的 `-enter` / `-exit`、`setTransition` 与
//! `setAnimation` 里。
//!
//! 这里只做"读文件 + 归一化", 不解释目标对象; 关键帧的展开由 `timeline` 完成
//! (它知道每个目标当前的变换状态)。

use std::{collections::BTreeMap, fs};

use serde::Deserialize;
use webgal_language_core::element::Transform;

use crate::project::Project;

/// 动画里的一帧。
///
/// `duration_ms` 是"从上一帧走到本帧"的时间 (v1 语义); 第一帧的时长按引擎的
/// `setStartState` 处理, 不参与等待。
#[derive(Debug, Clone, Default, PartialEq)]
pub struct AnimationFrame {
    pub duration_ms: u32,
    /// 脚本里的缓动名; 空串表示引擎默认 (easeInOut)。
    pub ease: String,
    /// 本帧写入的变换字段; 未写的字段沿用目标当前状态。
    pub transform: Transform,
}

impl AnimationFrame {
    /// 整段动画的可视时长 (各帧时长之和)。
    ///
    /// 第一帧是起点状态 (`setStartState` 立刻应用), 它的时长不参与推进。
    pub fn total_ms(frames: &[AnimationFrame]) -> u32 {
        frames.iter().skip(1).map(|frame| frame.duration_ms).sum()
    }
}

/// 动画不可用的原因; `code` 直接进 `plan.warnings`。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AnimationProblem {
    pub code: &'static str,
    pub message: String,
}

impl AnimationProblem {
    fn format(message: impl Into<String>) -> Self {
        Self {
            code: "WG_ANIMATION_FORMAT",
            message: message.into(),
        }
    }

    fn file(message: impl Into<String>) -> Self {
        Self {
            code: "WG_ANIMATION_FILE",
            message: message.into(),
        }
    }
}

/// 已加载的动画: 名字 → 关键帧序列。
#[derive(Debug, Default)]
pub struct AnimationLibrary {
    frames: BTreeMap<String, Vec<AnimationFrame>>,
    problems: BTreeMap<String, AnimationProblem>,
}

impl AnimationLibrary {
    /// 读取 `game/animation/animationTable.json` 里列出的全部动画。
    ///
    /// 没有动画目录、表缺失或表不是字符串数组时返回空库: 引擎也把"没有动画"当作
    /// 正常状态, 这里不把整次导出判为失败。
    pub fn load(project: &Project) -> Self {
        let mut library = Self::default();
        let Some(table) = project.asset_path("animation", "animationTable.json") else {
            return library;
        };
        let Ok(text) = fs::read_to_string(&table) else {
            return library;
        };
        let Ok(names) = serde_json::from_str::<Vec<String>>(&text) else {
            return library;
        };
        for name in names {
            let Some(path) = project.asset_path("animation", &name) else {
                library
                    .problems
                    .insert(name, AnimationProblem::file("动画文件不存在"));
                continue;
            };
            let text = match fs::read_to_string(&path) {
                Ok(text) => text,
                Err(error) => {
                    library
                        .problems
                        .insert(name, AnimationProblem::file(format!("无法读取: {error}")));
                    continue;
                }
            };
            match parse_animation(&text) {
                Ok(frames) => {
                    library.frames.insert(name, frames);
                }
                Err(problem) => {
                    library.problems.insert(name, problem);
                }
            }
        }
        library
    }

    /// 取动画关键帧; 名字不在表里或文件不可用时返回 `None`。
    pub fn frames(&self, name: &str) -> Option<&[AnimationFrame]> {
        self.frames.get(name).map(Vec::as_slice)
    }

    /// 动画不可用的原因。
    pub fn problem(&self, name: &str) -> Option<&AnimationProblem> {
        self.problems.get(name)
    }

    /// 动画总时长; 名字未知时为 `None`。
    pub fn total_ms(&self, name: &str) -> Option<u32> {
        self.frames(name).map(AnimationFrame::total_ms)
    }
}

/// 动画文件里的一帧 (v1 数组格式)。
#[derive(Debug, Deserialize)]
struct RawFrame {
    #[serde(default)]
    duration: u32,
    #[serde(default)]
    ease: Option<String>,
    #[serde(flatten)]
    transform: Transform,
}

/// 解析一份动画文件。
///
/// 目前只认 v1 (顶层数组); v2 (`{ "version": 2, "keyframes": [...] }`) 的
/// `relative` / `inherit` 语义与 v1 不同, 在没对照过行为之前不猜。
fn parse_animation(text: &str) -> Result<Vec<AnimationFrame>, AnimationProblem> {
    let value: serde_json::Value = serde_json::from_str(text)
        .map_err(|error| AnimationProblem::format(format!("JSON 解析失败: {error}")))?;
    if value.is_object() && value.get("keyframes").is_some() {
        return Err(AnimationProblem::format(
            "v2 keyframes 动画暂不支持 (只支持顶层数组的旧格式)",
        ));
    }
    if !value.is_array() {
        return Err(AnimationProblem::format(
            "动画文件既不是数组也不是 v2 keyframes",
        ));
    }
    let raw: Vec<RawFrame> = serde_json::from_str(text)
        .map_err(|error| AnimationProblem::format(format!("关键帧解析失败: {error}")))?;
    if raw.is_empty() {
        return Err(AnimationProblem::format("动画里没有关键帧"));
    }
    Ok(raw
        .into_iter()
        .map(|frame| AnimationFrame {
            duration_ms: frame.duration,
            ease: frame.ease.unwrap_or_default(),
            transform: frame.transform,
        })
        .collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_v1_keyframes() {
        let frames = parse_animation(
            r#"[
                { "alpha": 0, "position": { "x": -50, "y": 0 }, "blur": 5, "duration": 0 },
                { "alpha": 1, "position": { "x": 0, "y": 0 }, "blur": 0, "duration": 500, "ease": "circOut" }
            ]"#,
        )
        .expect("v1 应当解析成功");
        assert_eq!(frames.len(), 2);
        assert_eq!(frames[0].duration_ms, 0);
        assert_eq!(frames[0].ease, "");
        assert_eq!(frames[0].transform.alpha, Some(0.0));
        assert_eq!(frames[0].transform.blur, Some(5));
        assert_eq!(
            frames[0].transform.position.and_then(|position| position.x),
            Some(-50)
        );
        assert_eq!(frames[1].duration_ms, 500);
        assert_eq!(frames[1].ease, "circOut");
        assert_eq!(AnimationFrame::total_ms(&frames), 500);
    }

    #[test]
    fn parses_film_filter_switches_as_numbers() {
        let frames = parse_animation(r#"[ { "oldFilm": 1, "duration": 0 } ]"#)
            .expect("滤镜开关应当解析成功");
        assert_eq!(frames[0].transform.old_film, Some(true));
    }

    #[test]
    fn rejects_v2_keyframes() {
        let problem = parse_animation(
            r#"{ "version": 2, "keyframes": [ { "time": 250, "position": { "x": -100 } } ] }"#,
        )
        .expect_err("v2 尚未支持");
        assert_eq!(problem.code, "WG_ANIMATION_FORMAT");
        assert!(problem.message.contains("v2"));
    }

    #[test]
    fn rejects_empty_and_unknown_files() {
        assert!(parse_animation("[]").is_err());
        assert!(parse_animation(r#"{ "foo": 1 }"#).is_err());
        assert!(parse_animation("not json").is_err());
    }
}
